import React, { createContext, useContext, useState, useEffect } from 'react';

const LocationContext = createContext();

export const LocationProvider = ({ children }) => {
  const [currentLocation, setCurrentLocation] = useState(null);
  const [nearbyUsers, setNearbyUsers] = useState([]);
  const [locationStatus, setLocationStatus] = useState('inactive'); // active, inactive, passport
  const [isPassportMode, setIsPassportMode] = useState(false);
  const [realTimeUpdates, setRealTimeUpdates] = useState([]);

  return (
    <LocationContext.Provider value={{
      currentLocation, setCurrentLocation,
      nearbyUsers, setNearbyUsers,
      locationStatus, setLocationStatus,
      isPassportMode, setIsPassportMode,
      realTimeUpdates, setRealTimeUpdates
    }}>
      {children}
    </LocationContext.Provider>
  );
};

export const useLocation = () => useContext(LocationContext);
